//! Read Codex CLI credentials for LLM authentication.//!//! When `LLM_USE_CODEX_AUTH=true`, IronClaw reads the Codex CLI's//! `auth.json` file (default: `~/.codex/auth.json`) and extracts//! credentials. This lets IronClaw piggyback on a Codex login without//! implementing its own OAuth flow.//!//! Codex supports two auth modes://! - **API key** (`auth_mode: "apiKey"`) → uses `OPENAI_API_KEY` field//!   against `api.openai.com/v1`.//! - **ChatGPT** (`auth_mode: "chatgpt"`) → uses `tokens.access_token`//!   (OAuth JWT) against `chatgpt.com/backend-api/codex`.//!//! When in ChatGPT mode, the provider supports automatic token refresh//! on 401 responses using the `refresh_token` from `auth.json`.use std::path::{Path, PathBuf};use secrecy::{ExposeSecret, SecretString};use serde::{Deserialize, Serialize};/// ChatGPT backend API endpoint used by Codex in ChatGPT auth mode.const CHATGPT_BACKEND_URL: &str = "https://chatgpt.com/backend-api/codex";/// Standard OpenAI API endpoint used by Codex in API key mode.const OPENAI_API_URL: &str = "https://api.openai.com/v1";/// OAuth token refresh endpoint (same as Codex CLI).const REFRESH_TOKEN_URL: &str = "https://auth.openai.com/oauth/token";/// OAuth client ID used for token refresh (same as Codex CLI).const CLIENT_ID: &str = "app_EMoamEEZ73f0CkXaXp7hrann";/// Credentials extracted from Codex's `auth.json`.#[derive(Debug, Clone)]pub struct CodexCredentials {    /// The bearer token (API key or ChatGPT access_token).    pub token: SecretString,    /// Whether this is a ChatGPT OAuth token (vs. an OpenAI API key).    pub is_chatgpt_mode: bool,    /// OAuth refresh token (only present in ChatGPT mode).    pub refresh_token: Option<SecretString>,    /// Path to the auth.json file (for persisting refreshed tokens).    pub auth_path: Option<PathBuf>,}impl CodexCredentials {    /// Returns the correct base URL for the auth mode.    ///    /// - ChatGPT mode → `https://chatgpt.com/backend-api/codex`    /// - API key mode → `https://api.openai.com/v1`    pub fn base_url(&self) -> &'static str {        if self.is_chatgpt_mode {            CHATGPT_BACKEND_URL        } else {            OPENAI_API_URL        }    }}/// Partial representation of Codex's `$CODEX_HOME/auth.json`.#[derive(Debug, Deserialize)]struct CodexAuthJson {    auth_mode: Option<String>,    #[serde(rename = "OPENAI_API_KEY")]    openai_api_key: Option<String>,    tokens: Option<CodexTokens>,}#[derive(Debug, Deserialize)]struct CodexTokens {    access_token: SecretString,    refresh_token: Option<SecretString>,}/// Request body for OAuth token refresh.#[derive(Serialize)]struct RefreshRequest<'a> {    client_id: &'a str,    grant_type: &'a str,    refresh_token: &'a str,}/// Response from the OAuth token refresh endpoint.#[derive(Debug, Deserialize)]struct RefreshResponse {    access_token: SecretString,    refresh_token: Option<SecretString>,}/// Default path used by Codex CLI: `~/.codex/auth.json`.pub fn default_codex_auth_path() -> PathBuf {    let home_dir = dirs::home_dir().unwrap_or_else(|| {        tracing::warn!(            "Could not determine home directory; falling back to current working directory for Codex auth.json path"        );        PathBuf::from(".")    });    home_dir.join(".codex").join("auth.json")}/// Load credentials from a Codex `auth.json` file.////// Returns `None` if the file is missing, unreadable, or contains/// no usable credentials.pub fn load_codex_credentials(path: &Path) -> Option<CodexCredentials> {    let content = match std::fs::read_to_string(path) {        Ok(c) => c,        Err(e) => {            tracing::debug!("Could not read Codex auth file {}: {}", path.display(), e);            return None;        }    };    let auth: CodexAuthJson = match serde_json::from_str(&content) {        Ok(a) => a,        Err(e) => {            tracing::warn!("Failed to parse Codex auth file {}: {}", path.display(), e);            return None;        }    };    let is_chatgpt = auth        .auth_mode        .as_deref()        .map(|m| m == "chatgpt" || m == "chatgptAuthTokens")        .unwrap_or(false);    // API key mode: use OPENAI_API_KEY field.    if !is_chatgpt {        if let Some(key) = auth.openai_api_key.filter(|k| !k.is_empty()) {            tracing::info!("Loaded API key from Codex auth.json (API key mode)");            return Some(CodexCredentials {                token: SecretString::from(key),                is_chatgpt_mode: false,                refresh_token: None,                auth_path: None,            });        }        // If auth_mode was explicitly `apiKey`, do not fall back to checking for a token.        if auth.auth_mode.is_some() {            return None;        }    }    // ChatGPT mode: use access_token as bearer token.    if let Some(tokens) = auth.tokens        && !tokens.access_token.expose_secret().is_empty()    {        tracing::info!(            "Loaded access token from Codex auth.json (ChatGPT mode, base_url={})",            CHATGPT_BACKEND_URL        );        return Some(CodexCredentials {            token: tokens.access_token,            is_chatgpt_mode: true,            refresh_token: tokens.refresh_token,            auth_path: Some(path.to_path_buf()),        });    }    tracing::debug!(        "Codex auth.json at {} contains no usable credentials",        path.display()    );    None}/// Attempt to refresh an expired access token using the refresh token.////// On success, returns the new `access_token` and persists the refreshed/// tokens back to `auth.json`. This follows the same OAuth protocol as/// Codex CLI (`POST https://auth.openai.com/oauth/token`).////// Returns `None` if the refresh token is missing, the request fails,/// or the response is malformed.